package org.json; import java.util.*; public class JSONArray {private final List<Object> vals=new ArrayList<>(); public JSONArray() {} public JSONArray put(Object v){vals.add(v);return this;} public int length(){return vals.size();} public JSONObject optJSONObject(int i){return i>=0&&i<vals.size()&&vals.get(i) instanceof JSONObject?(JSONObject)vals.get(i):null;} public String getString(int i){return String.valueOf(vals.get(i));}}